import React, { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, ArrowLeft, Check, CheckCircle2, ChevronRight, FileText, Globe2, Loader2, Network, RefreshCw, Search, ShieldCheck, Sparkles, UsersRound, X } from 'lucide-react';
import { useData } from '../../context/DataContext';
import { getToolRoom } from './toolRoomCatalog';
import ToolRoomShell from './ToolRoomShell';
import useToolRoomLaunch from './useToolRoomLaunch';
import { useToolRooms } from '../../context/ToolRoomContext';
import { buildMissionDocuments, MISSION_SCOPES, MISSION_TYPES, requestMissionImpact, requestMissionOperations } from '../../services/ai-next/MissionService';
import { executeOperationsWithRollback, prepareOperations, validateOperationAgainstDocument } from '../../services/ai-next/MissionExecutionService';
import { loadMissionHistory, saveMissionHistoryEntry } from '../../services/ai-next/MissionHistoryService';
import { getEntitySnapshots, saveEntitySnapshot } from '../../services/db';
import { saveLocalSnapshot } from '../../services/localDb';
import { flushPendingCanonSync, getCanonStats, loadCanonGraph, loadCanonGraphRemote, saveCanonGraph, saveCanonGraphRemote, setCanonFactStatusByTriple, setCanonItemStatus, updateCanonEntity, upsertCanonEntities, upsertCanonFacts, upsertCanonRelations } from '../../services/ai-next/CanonGraphService';
import { migrateRoomState } from '../../services/ai-next/MissionMigrationService';

const DEFAULT_CONSTRAINTS = { preserveCanon: true, preserveStyle: true, noAutomaticWrites: true, preserveEnding: true };
const MODE_CARDS = [
    ['develop_canon', Globe2, 'Desarrollar canon', 'Define reglas, hechos, lugares, cronología y relaciones.'],
    ['improve_content', FileText, 'Escribir y reescribir', 'Mejora escenas o documentos conservando la intención.'],
    ['modify_structure', Network, 'Diseñar estructura', 'Organiza capítulos, escenas, conflictos y consecuencias.'],
    ['update_character', UsersRound, 'Trabajar personajes', 'Actualiza fichas y detecta apariciones relacionadas.'],
    ['review_continuity', Search, 'Revisar continuidad', 'Analiza contradicciones y dependencias sin escribir.'],
    ['sync_canon', ShieldCheck, 'Sincronizar canon', 'Propone cambios coordinados entre el canon y el manuscrito.'],
];

const typeLabel = (id) => MISSION_TYPES.find((item) => item.id === id)?.label || id;
const STATUS_META = {
    idle: ['Listo para configurar', 'text-[var(--text-muted)]', 'bg-[var(--bg-app)]'],
    analyzing: ['Analizando impacto', 'text-cyan-700', 'bg-cyan-500/10'],
    ready: ['Impacto listo para revisar', 'text-cyan-700', 'bg-cyan-500/10'],
    generating: ['Preparando operaciones', 'text-amber-700', 'bg-amber-500/10'],
    review: ['Listo para revisión', 'text-emerald-700', 'bg-emerald-500/10'],
    applying: ['Aplicando cambios', 'text-indigo-700', 'bg-indigo-500/10'],
    error: ['Requiere atención', 'text-red-700', 'bg-red-500/10'],
};

const MissionStatusBar = ({ status, step, mission, documents, impact, result }) => {
    const [label, color, background] = STATUS_META[status] || STATUS_META.idle;
    const stepLabels = { type: 'Tipo', objective: 'Objetivo', scope: 'Alcance', impact: 'Impacto', review: 'Revisión' };
    return <section className="mt-5 grid gap-3 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-4 sm:grid-cols-2 lg:grid-cols-4"><div className="min-w-0"><p className="text-[9px] font-black uppercase tracking-[0.16em] text-[var(--text-muted)]">Estado de misión</p><span className={`mt-2 inline-flex rounded-full px-2.5 py-1 text-xs font-black ${color} ${background}`}>{label}</span><p className="mt-2 truncate text-[11px] text-[var(--text-muted)]">{mission.objective || 'Sin objetivo definido'}</p></div><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-[var(--text-muted)]">Progreso</p><p className="mt-2 text-sm font-black">{stepLabels[step] || 'Configuración'}</p><p className="mt-1 text-[11px] text-[var(--text-muted)]">Contexto: {documents.length} documentos</p></div><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-[var(--text-muted)]">Confianza del análisis</p><p className="mt-2 text-sm font-black">{impact ? `${Math.round((impact.confidence ?? 0.5) * 100)}%` : 'Pendiente'}</p><p className="mt-1 text-[11px] text-[var(--text-muted)]">{impact ? `${impact.affectedDocuments.length} documentos impactados` : 'Analiza la misión para calcularla'}</p></div><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-[var(--text-muted)]">Revisión</p><p className="mt-2 text-sm font-black">{result ? `${result.operations.length} operaciones` : 'Sin operaciones'}</p><p className="mt-1 text-[11px] text-[var(--text-muted)]">{impact ? `Riesgo ${impact.risk}` : 'Aún no generada'}</p></div></section>;
};

const SnapshotPanel = ({ snapshots, onRestore }) => {
    if (!snapshots.length) return null;
    return <section className="mt-5 rounded-2xl border border-emerald-500/20 bg-emerald-500/5 p-4"><div className="flex items-center justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-emerald-700">Protección de aplicación</p><h3 className="mt-1 text-sm font-black">Snapshots creados</h3><p className="mt-1 text-xs text-[var(--text-muted)]">Puntos de restauración creados antes de aplicar cambios.</p></div><ShieldCheck size={19} className="text-emerald-600" /></div><div className="mt-3 grid gap-2 sm:grid-cols-2">{snapshots.map((snapshot) => <div key={`${snapshot.documentId}-${snapshot.createdAt}`} className="rounded-xl border border-emerald-500/15 bg-[var(--bg-editor)] p-3"><div className="flex items-start justify-between gap-2"><p className="text-xs font-black">{snapshot.title}</p><button type="button" onClick={() => onRestore(snapshot)} className="rounded-lg border border-emerald-500/25 px-2 py-1 text-[10px] font-black text-emerald-700 hover:bg-emerald-500/10">Restaurar</button></div><p className="mt-1 text-[10px] text-[var(--text-muted)]">Snapshot previo · {snapshot.trigger} · {new Date(snapshot.createdAt).toLocaleTimeString('es-MX')}</p></div>)}</div></section>;
};

const MissionDocumentPicker = ({ documents, selectedIds, setSelectedIds }) => (
    <div className="mt-3 grid max-h-64 grid-cols-1 gap-2 overflow-y-auto pr-1 sm:grid-cols-2">
        {documents.map((document) => {
            const selected = selectedIds.includes(document.id);
            return <button type="button" key={document.id} onClick={() => setSelectedIds((current) => selected ? current.filter((id) => id !== document.id) : [...current, document.id])} className={`rounded-xl border p-3 text-left transition-colors ${selected ? 'border-indigo-500 bg-indigo-500/10' : 'border-[var(--border-main)] hover:border-indigo-500/50'}`}><div className="flex items-center justify-between gap-2"><span className="truncate text-xs font-black">{document.title}</span>{selected && <Check size={14} className="shrink-0 text-indigo-500" />}</div><span className="mt-1 block text-[10px] uppercase tracking-wider text-[var(--text-muted)]">{document.type}</span></button>;
        })}
    </div>
);

const ImpactPanel = ({ impact, onContinue }) => {
    if (!impact) return null;
    return <section className="mt-5 rounded-2xl border border-cyan-500/25 bg-cyan-500/5 p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-cyan-600">Mapa de impacto</p><h3 className="mt-1 text-sm font-black">{impact.summary}</h3></div><span className="rounded-full bg-cyan-500/10 px-2.5 py-1 text-[10px] font-black uppercase text-cyan-700">Riesgo {impact.risk}</span></div><div className="mt-4 space-y-2">{impact.affectedDocuments.map((document) => <div key={document.documentId} className="flex items-start gap-3 rounded-xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-3"><div className={`mt-0.5 h-2.5 w-2.5 shrink-0 rounded-full ${document.impact === 'high' ? 'bg-red-500' : document.impact === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`} /><div className="min-w-0"><p className="text-xs font-black">{document.title} <span className="font-normal text-[var(--text-muted)]">· {document.action}</span></p><p className="mt-1 text-[11px] leading-relaxed text-[var(--text-muted)]">{document.reason}</p></div></div>)}</div>{impact.canonFacts?.length > 0 && <div className="mt-4 rounded-xl bg-[var(--bg-editor)] p-3 text-xs"><p className="font-black">Hechos canónicos propuestos</p>{impact.canonFacts.map((fact, index) => <p key={`${fact.subject}-${index}`} className="mt-1 text-[var(--text-muted)]">{fact.subject} {fact.predicate} {fact.object} · <strong>{fact.status}</strong></p>)}</div>}{impact.warnings?.length > 0 && <div className="mt-4 flex items-start gap-2 text-xs text-amber-700"><AlertTriangle size={14} className="mt-0.5 shrink-0" />{impact.warnings.join(' ')}</div>}<button type="button" onClick={onContinue} className="mt-4 inline-flex items-center gap-2 rounded-xl bg-cyan-600 px-3 py-2 text-xs font-black text-white hover:bg-cyan-500"><ChevronRight size={14} /> Generar operaciones</button></section>;
};

const LegacyReviewPanel = ({ result, onApprove, onReject, onEdit, onApplyApproved, pendingCount }) => {
    if (!result) return null;
    return <section className="mt-5 rounded-2xl border border-emerald-500/25 bg-emerald-500/5 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-emerald-600">Revisión del Constructor Global</p><h3 className="mt-1 text-sm font-black">{result.summary}</h3></div><div className="flex items-center gap-2"><span className="text-[10px] font-black uppercase text-emerald-700">{result.operations.length} operación(es)</span>{pendingCount > 1 && <button type="button" onClick={onApplyApproved} className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-700 px-2.5 py-1.5 text-[10px] font-black text-white"><Check size={13} /> Aplicar juntas ({pendingCount})</button>}</div></div><div className="mt-4 space-y-3">{result.operations.map((operation) => <article key={operation.id} className="rounded-xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-3"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-black">{operation.title}</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">{operation.action} · riesgo {operation.risk}</p></div><span className="rounded-full bg-amber-500/10 px-2 py-1 text-[9px] font-black uppercase text-amber-700">{operation.status}</span></div><p className="mt-2 text-xs leading-relaxed text-[var(--text-muted)]">{operation.reason}</p>{operation.originalText && <div className="mt-3 grid gap-2 md:grid-cols-2"><div><p className="text-[9px] font-black uppercase text-red-500">Original</p><p className="mt-1 rounded-lg bg-red-500/5 p-2 text-xs">{operation.originalText}</p></div><label className="text-[9px] font-black uppercase text-emerald-600">Propuesta<textarea value={operation.replacementText} onChange={(event) => onEdit(operation.id, event.target.value)} rows={3} className="mt-1 w-full rounded-lg border border-emerald-500/20 bg-emerald-500/5 p-2 text-xs font-normal normal-case outline-none focus:border-emerald-500" /></label></div>}<div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={() => onApprove(operation.id)} className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-2.5 py-1.5 text-[10px] font-black text-white"><Check size={13} /> Aprobar</button><button type="button" onClick={() => onReject(operation.id)} className="inline-flex items-center gap-1.5 rounded-lg border border-[var(--border-main)] px-2.5 py-1.5 text-[10px] font-black"><X size={13} /> Dejar pendiente</button></div></article>)}</div></section>;
};

const ReviewPanel = ({ result, onApprove, onReject, onEdit, onApplyApproved, onRegenerateDocument, pendingCount }) => {
    const [filter, setFilter] = useState('all');
    if (!result) return null;
    const operations = result.operations || [];
    const resolved = operations.filter((operation) => ['applied', 'canon'].includes(operation.status));
    const visible = operations.filter((operation) => filter === 'all' || (filter === 'pending' ? !['applied', 'canon'].includes(operation.status) : filter === 'resolved' ? ['applied', 'canon'].includes(operation.status) : operation.action === 'review'));
    const actionLabels = { patch: 'Parche', replace: 'Reemplazo', create: 'Crear', fact: 'Hecho canónico', review: 'Revisión' };
    const statusLabels = { pending: 'Pendiente', pending_review: 'Pendiente', applied: 'Aplicada', canon: 'Canónica' };
    return <section className="mt-5 rounded-2xl border border-emerald-500/25 bg-emerald-500/5 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-emerald-600">Revisión del Constructor Global</p><h3 className="mt-1 text-sm font-black">{result.summary}</h3></div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[var(--bg-editor)] px-2.5 py-1 text-[10px] font-black text-[var(--text-muted)]">{resolved.length}/{operations.length} resueltas</span>{pendingCount > 1 && <button type="button" onClick={onApplyApproved} className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-700 px-2.5 py-1.5 text-[10px] font-black text-white"><Check size={13} /> Aplicar juntas ({pendingCount})</button>}</div></div><div className="mt-4 flex flex-wrap items-center gap-2 border-y border-emerald-500/15 py-3"><span className="mr-1 text-[10px] font-black uppercase tracking-wider text-[var(--text-muted)]">Mostrar</span>{[['all', `Todas (${operations.length})`], ['pending', `Pendientes (${operations.length - resolved.length})`], ['resolved', `Resueltas (${resolved.length})`], ['review', `Solo análisis (${operations.filter((operation) => operation.action === 'review').length})`]].map(([value, label]) => <button type="button" key={value} onClick={() => setFilter(value)} className={`rounded-full px-2.5 py-1 text-[10px] font-black ${filter === value ? 'bg-emerald-600 text-white' : 'border border-[var(--border-main)] text-[var(--text-muted)]'}`}>{label}</button>)}</div><div className="mt-4 space-y-3">{visible.length === 0 ? <p className="rounded-xl border border-dashed border-emerald-500/25 p-4 text-xs text-[var(--text-muted)]">No hay operaciones en esta vista.</p> : visible.map((operation) => <article key={operation.id} className="rounded-xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-3"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-black">{operation.title}</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">{actionLabels[operation.action] || operation.action} · riesgo {operation.risk}</p></div><span className={`rounded-full px-2 py-1 text-[9px] font-black uppercase ${['applied', 'canon'].includes(operation.status) ? 'bg-emerald-500/10 text-emerald-700' : operation.action === 'review' ? 'bg-blue-500/10 text-blue-700' : 'bg-amber-500/10 text-amber-700'}`}>{statusLabels[operation.status] || operation.status}</span></div><p className="mt-2 text-xs leading-relaxed text-[var(--text-muted)]">{operation.reason}</p>{operation.originalText && <div className="mt-3 grid gap-2 md:grid-cols-2"><div><p className="text-[9px] font-black uppercase text-red-500">Original</p><p className="mt-1 rounded-lg bg-red-500/5 p-2 text-xs">{operation.originalText}</p></div><label className="text-[9px] font-black uppercase text-emerald-600">Propuesta<textarea value={operation.replacementText} onChange={(event) => onEdit(operation.id, event.target.value)} rows={3} className="mt-1 w-full rounded-lg border border-emerald-500/20 bg-emerald-500/5 p-2 text-xs font-normal normal-case outline-none focus:border-emerald-500" /></label></div>}<div className="mt-3 flex flex-wrap gap-2">{!['applied', 'canon'].includes(operation.status) && operation.action !== 'review' && <button type="button" onClick={() => onApprove(operation.id)} className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-600 px-2.5 py-1.5 text-[10px] font-black text-white"><Check size={13} /> Aprobar</button>}{!['applied', 'canon'].includes(operation.status) && onRegenerateDocument && operation.documentId && <button type="button" onClick={() => onRegenerateDocument(operation.documentId)} className="inline-flex items-center gap-1.5 rounded-lg border border-indigo-500/30 px-2.5 py-1.5 text-[10px] font-black text-indigo-600"><RefreshCw size={13} /> Regenerar documento</button>}{!['applied', 'canon'].includes(operation.status) && <button type="button" onClick={() => onReject(operation.id)} className="inline-flex items-center gap-1.5 rounded-lg border border-[var(--border-main)] px-2.5 py-1.5 text-[10px] font-black"><X size={13} /> Dejar pendiente</button>}</div></article>)}</div></section>;
};

const CanonPanel = ({ graph, onStatusChange }) => {
    const stats = getCanonStats(graph);
    const entities = [...new Set([...graph.facts.flatMap((fact) => [fact.subject, fact.object]), ...graph.relations.flatMap((relation) => [relation.source, relation.target])].filter(Boolean))];
    return <section className="mt-5 rounded-3xl border border-violet-500/20 bg-violet-500/5 p-5 lg:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-[9px] font-black uppercase tracking-[0.18em] text-violet-600">Canon estructurado</p><h3 className="mt-1 text-xl font-serif font-black">La memoria viva de la obra</h3><p className="mt-2 max-w-2xl text-xs leading-relaxed text-[var(--text-muted)]">Los hechos se guardan separados del texto y solo se vuelven canónicos cuando los apruebas.</p></div><div className="grid grid-cols-3 gap-2 text-center text-[10px]"><div className="rounded-xl bg-[var(--bg-editor)] p-2"><strong className="block text-lg">{stats.canonicalFacts}</strong>canónicos</div><div className="rounded-xl bg-[var(--bg-editor)] p-2"><strong className="block text-lg">{stats.pendingFacts}</strong>pendientes</div><div className="rounded-xl bg-[var(--bg-editor)] p-2"><strong className="block text-lg">{stats.relations}</strong>relaciones</div></div></div>{entities.length > 0 && <div className="mt-5 flex flex-wrap gap-2">{entities.slice(0, 20).map((entity) => <span key={entity} className="rounded-full border border-violet-500/20 bg-[var(--bg-editor)] px-3 py-1.5 text-[10px] font-black text-violet-700">{entity}</span>)}</div>}<div className="mt-5 space-y-2">{graph.facts.length === 0 ? <p className="rounded-xl border border-dashed border-violet-500/30 p-4 text-xs text-[var(--text-muted)]">Todavía no hay hechos estructurados. Las misiones de canon aparecerán aquí para revisión.</p> : graph.facts.slice(0, 12).map((fact) => <div key={fact.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-3"><div className="min-w-0"><p className="text-xs font-black">{fact.subject} <span className="text-violet-600">{fact.predicate}</span> {fact.object}</p><p className="mt-1 text-[10px] uppercase tracking-wider text-[var(--text-muted)]">{fact.status} · {fact.source}</p></div><div className="flex shrink-0 gap-2">{fact.status !== 'canon' && <button type="button" onClick={() => onStatusChange(fact.id, 'canon', 'facts')} className="inline-flex items-center gap-1 rounded-lg bg-violet-600 px-2.5 py-1.5 text-[10px] font-black text-white"><Check size={12} /> Convertir en canon</button>}{fact.status === 'canon' && <button type="button" onClick={() => onStatusChange(fact.id, 'obsolete', 'facts')} className="rounded-lg border border-[var(--border-main)] px-2.5 py-1.5 text-[10px] font-black">Marcar obsoleto</button>}</div></div>)}</div>{graph.relations.length > 0 && <div className="mt-5 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-4"><p className="text-[9px] font-black uppercase tracking-[0.16em] text-violet-600">Relaciones detectadas</p><div className="mt-2 space-y-2 text-xs text-[var(--text-muted)]">{graph.relations.slice(0, 8).map((relation) => <div key={relation.id} className="flex flex-wrap items-center justify-between gap-2"><p><strong className="text-[var(--text-main)]">{relation.source}</strong> {relation.predicate} <strong className="text-[var(--text-main)]">{relation.target}</strong> · {relation.status}</p>{relation.status !== 'canon' && <button type="button" onClick={() => onStatusChange(relation.id, 'canon', 'relations')} className="rounded-lg bg-violet-600 px-2 py-1 text-[10px] font-black text-white">Aprobar relación</button>}</div>)}</div></div>}</section>;
};

const LegacyMissionHistoryPanel = ({ entries }) => <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><div className="flex items-center justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-[0.18em] text-[var(--text-muted)]">Trazabilidad</p><h3 className="mt-1 text-xl font-serif font-black">Historial de misiones</h3></div><span className="text-xs font-black text-[var(--text-muted)]">{entries.length} guardadas</span></div>{entries.length === 0 ? <p className="mt-4 text-xs text-[var(--text-muted)]">Las ejecuciones y propuestas de esta sala aparecerán aquí.</p> : <div className="mt-4 space-y-2">{entries.slice(0, 5).map((entry) => <div key={entry.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-[var(--border-main)] p-3"><div><p className="text-xs font-black">{entry.mission?.objective || 'Misión del Constructor Global'}</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">{entry.mission?.type || '—'} · {entry.status || 'draft'} · {entry.updatedAt ? new Date(entry.updatedAt).toLocaleString('es-MX') : 'sin fecha'}</p></div><span className="rounded-full bg-indigo-500/10 px-2 py-1 text-[9px] font-black uppercase text-indigo-600">{entry.result?.operations?.length || 0} operaciones</span></div>)}</div>}</section>;

const MissionHistoryPanel = ({ entries }) => {
    const [expandedId, setExpandedId] = useState(null);
    const statusLabels = { ready_for_generation: 'Impacto listo', ready_for_review: 'Lista para revisar', partially_applied: 'Aplicada parcialmente', applied: 'Aplicada', stale: 'Obsoleta', failed: 'Fallida' };
    return <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><div className="flex items-center justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-[0.18em] text-[var(--text-muted)]">Trazabilidad</p><h3 className="mt-1 text-xl font-serif font-black">Historial de misiones</h3><p className="mt-1 text-xs text-[var(--text-muted)]">Consulta qué se analizó, qué se propuso y qué quedó pendiente.</p></div><span className="text-xs font-black text-[var(--text-muted)]">{entries.length} guardadas</span></div>{entries.length === 0 ? <p className="mt-4 text-xs text-[var(--text-muted)]">Las ejecuciones y propuestas de esta sala aparecerán aquí.</p> : <div className="mt-4 space-y-2">{entries.slice(0, 8).map((entry) => { const operations = entry.result?.operations || entry.operations || []; const pending = operations.filter((operation) => !['applied', 'canon'].includes(operation.status)); const expanded = expandedId === entry.id; return <article key={entry.id} className="rounded-xl border border-[var(--border-main)] bg-[var(--bg-app)]"><button type="button" onClick={() => setExpandedId(expanded ? null : entry.id)} className="flex w-full flex-wrap items-center justify-between gap-3 p-3 text-left"><div className="min-w-0"><p className="truncate text-xs font-black">{entry.mission?.objective || 'Misión del Constructor Global'}</p><p className="mt-1 text-[10px] text-[var(--text-muted)]">{entry.mission?.type || '—'} · {entry.updatedAt ? new Date(entry.updatedAt).toLocaleString('es-MX') : 'sin fecha'}</p></div><div className="flex items-center gap-2"><span className={`rounded-full px-2 py-1 text-[9px] font-black uppercase ${entry.status === 'failed' || entry.status === 'stale' ? 'bg-red-500/10 text-red-700' : entry.status === 'applied' ? 'bg-emerald-500/10 text-emerald-700' : 'bg-indigo-500/10 text-indigo-700'}`}>{statusLabels[entry.status] || entry.status || 'Borrador'}</span><span className="text-[10px] font-black text-[var(--text-muted)]">{operations.length} op.</span><ChevronRight size={14} className={expanded ? 'rotate-90' : ''} /></div></button>{expanded && <div className="border-t border-[var(--border-main)] p-3 text-xs"><div className="grid gap-2 sm:grid-cols-3"><div><span className="text-[10px] text-[var(--text-muted)]">Alcance</span><strong className="mt-1 block">{entry.mission?.scope || 'automático'}</strong></div><div><span className="text-[10px] text-[var(--text-muted)]">Impacto</span><strong className="mt-1 block">{entry.impact?.affectedDocuments?.length || 0} documentos · riesgo {entry.impact?.risk || '—'}</strong></div><div><span className="text-[10px] text-[var(--text-muted)]">Pendientes</span><strong className="mt-1 block">{pending.length}</strong></div></div>{entry.error && <p className="mt-3 rounded-lg bg-red-500/5 p-2 text-red-700">{entry.error}</p>}{pending.length > 0 && <p className="mt-3 rounded-lg bg-amber-500/5 p-2 text-amber-700">Hay operaciones pendientes de aprobación o sincronización.</p>}</div>}</article>; })}</div>}</section>;
};

const ENTITY_TYPES = ['concept', 'character', 'place', 'faction', 'object', 'rule', 'event'];
const EntityExplorer = ({ graph, documents = [], onGraphChange, onOpenDocument, focusName }) => {
    const [query, setQuery] = useState('');
    const [filter, setFilter] = useState('all');
    const [selectedId, setSelectedId] = useState(null);
    const [newName, setNewName] = useState('');
    const entities = graph.entities || [];
    const filtered = entities.filter((entity) => (filter === 'all' || entity.status === filter) && entity.name.toLowerCase().includes(query.toLowerCase()));
    const selected = entities.find((entity) => entity.id === selectedId) || entities.find((entity) => entity.name === focusName) || filtered[0] || null;
    const connectedFacts = selected ? graph.facts.filter((fact) => [fact.subject, fact.object].includes(selected.name)) : [];
    const connectedRelations = selected ? graph.relations.filter((relation) => [relation.source, relation.target].includes(selected.name)) : [];
    const appearances = selected ? documents.filter((document) => document.content.toLowerCase().includes(selected.name.toLowerCase())).map((document) => ({ documentId: document.id, title: document.title, excerpt: document.content.slice(Math.max(0, document.content.toLowerCase().indexOf(selected.name.toLowerCase()) - 70), Math.min(document.content.length, document.content.toLowerCase().indexOf(selected.name.toLowerCase()) + selected.name.length + 100)) })) : [];
    const update = (patch) => selected && onGraphChange(updateCanonEntity(graph, selected.id, patch));
    const create = () => { const name = newName.trim(); if (!name) return; const next = upsertCanonEntities(graph, [{ name, type: 'concept', status: 'proposed' }]); onGraphChange(next); setNewName(''); setSelectedId(next.entities[0]?.id || null); };
    return <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-[9px] font-black uppercase tracking-[0.18em] text-violet-600">Explorador de canon</p><h3 className="mt-1 text-xl font-serif font-black">Entidades y dependencias</h3><p className="mt-2 text-xs text-[var(--text-muted)]">Selecciona una entidad para ver qué hechos, relaciones y apariciones dependen de ella.</p></div><div className="flex gap-2"><input value={newName} onChange={(event) => setNewName(event.target.value)} placeholder="Nueva entidad" className="w-36 rounded-xl border border-[var(--border-main)] bg-[var(--bg-app)] px-3 py-2 text-xs outline-none" /><button type="button" onClick={create} disabled={!newName.trim()} className="rounded-xl bg-violet-600 px-3 py-2 text-xs font-black text-white disabled:opacity-50">Añadir</button></div></div><div className="mt-5 grid grid-cols-1 gap-4 lg:grid-cols-[280px_minmax(0,1fr)]"><aside><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar entidad" className="w-full rounded-xl border border-[var(--border-main)] bg-[var(--bg-app)] px-3 py-2 text-xs outline-none focus:border-violet-500" /><div className="mt-3 flex flex-wrap gap-1.5">{['all', 'canon', 'proposed', 'conflict', 'obsolete'].map((value) => <button type="button" key={value} onClick={() => setFilter(value)} className={`rounded-full px-2.5 py-1 text-[10px] font-black ${filter === value ? 'bg-violet-600 text-white' : 'border border-[var(--border-main)] text-[var(--text-muted)]'}`}>{value === 'all' ? 'Todas' : value}</button>)}</div><div className="mt-3 max-h-64 space-y-1 overflow-y-auto">{filtered.length === 0 ? <p className="rounded-xl border border-dashed border-[var(--border-main)] p-4 text-xs text-[var(--text-muted)]">No hay entidades con este filtro.</p> : filtered.map((entity) => <button type="button" key={entity.id} onClick={() => setSelectedId(entity.id)} className={`w-full rounded-xl px-3 py-2 text-left ${selected?.id === entity.id ? 'bg-violet-500/10 text-violet-700' : 'hover:bg-[var(--accent-soft)]'}`}><span className="block truncate text-xs font-black">{entity.name}</span><span className="text-[10px] text-[var(--text-muted)]">{entity.type} · {entity.status}</span></button>)}</div></aside>{selected ? <main className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-app)] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-wider text-violet-600">Entidad seleccionada</p><input value={selected.name} onChange={(event) => update({ name: event.target.value })} className="mt-1 w-full min-w-52 border-b border-[var(--border-main)] bg-transparent py-1 text-lg font-serif font-black outline-none focus:border-violet-500" /></div><div className="flex gap-2"><select value={selected.type} onChange={(event) => update({ type: event.target.value })} className="rounded-xl border border-[var(--border-main)] bg-[var(--bg-editor)] px-3 py-2 text-xs font-black">{ENTITY_TYPES.map((value) => <option key={value} value={value}>{value}</option>)}</select><select value={selected.status} onChange={(event) => update({ status: event.target.value })} className="rounded-xl border border-[var(--border-main)] bg-[var(--bg-editor)] px-3 py-2 text-xs font-black"><option value="proposed">Propuesto</option><option value="in_review">En revisión</option><option value="canon">Canónico</option><option value="conflict">En conflicto</option><option value="obsolete">Obsoleto</option></select></div></div><label className="mt-4 block text-[10px] font-black uppercase tracking-wider text-[var(--text-muted)]">Notas<textarea value={selected.notes} onChange={(event) => update({ notes: event.target.value })} rows={2} className="mt-1 w-full resize-none rounded-xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-3 text-xs font-normal normal-case outline-none focus:border-violet-500" /></label><div className="mt-5 grid gap-3 md:grid-cols-2"><div><p className="text-[9px] font-black uppercase tracking-wider text-violet-600">Hechos dependientes ({connectedFacts.length})</p><div className="mt-2 space-y-1">{connectedFacts.map((fact) => <p key={fact.id} className="rounded-lg bg-[var(--bg-editor)] p-2 text-xs">{fact.subject} {fact.predicate} {fact.object}</p>)}</div></div><div><p className="text-[9px] font-black uppercase tracking-wider text-violet-600">Relaciones ({connectedRelations.length})</p><div className="mt-2 space-y-1">{connectedRelations.map((relation) => <p key={relation.id} className="rounded-lg bg-[var(--bg-editor)] p-2 text-xs">{relation.source} {relation.predicate} {relation.target}</p>)}</div></div></div><div className="mt-5"><p className="text-[9px] font-black uppercase tracking-wider text-violet-600">Apariciones detectadas ({appearances.length})</p><div className="mt-2 max-h-40 space-y-1 overflow-y-auto">{appearances.length === 0 ? <p className="rounded-lg bg-[var(--bg-editor)] p-2 text-xs text-[var(--text-muted)]">No se encontró esta entidad en el contenido disponible.</p> : appearances.slice(0, 8).map((appearance) => <button type="button" key={appearance.documentId} onClick={() => onOpenDocument?.(appearance.documentId)} className="block w-full rounded-lg bg-[var(--bg-editor)] p-2 text-left text-xs hover:border hover:border-violet-500"><strong>{appearance.title}</strong><span className="ml-2 text-[var(--text-muted)]">…{appearance.excerpt}…</span><span className="mt-1 block text-[10px] font-black text-violet-600">Abrir documento →</span></button>)}</div></div></main> : <main className="flex min-h-48 items-center justify-center rounded-2xl border border-dashed border-[var(--border-main)] p-6 text-center text-xs text-[var(--text-muted)]">Crea o selecciona una entidad para explorar el canon.</main>}</div></section>;
};

const RelationCanvas = ({ graph, onSelectEntity }) => {
    const entities = graph.entities.slice(0, 12);
    const width = 760;
    const height = Math.max(220, Math.ceil(entities.length / 4) * 110);
    const positions = new Map(entities.map((entity, index) => [entity.name, { x: 110 + (index % 4) * 180, y: 55 + Math.floor(index / 4) * 105 }]));
    const edges = graph.relations.filter((relation) => positions.has(relation.source) && positions.has(relation.target));
    return <section className="mt-5 rounded-3xl border border-indigo-500/20 bg-indigo-500/5 p-5 lg:p-7"><p className="text-[9px] font-black uppercase tracking-[0.18em] text-indigo-600">Mapa de relaciones</p><h3 className="mt-1 text-xl font-serif font-black">Red narrativa</h3><p className="mt-2 text-xs text-[var(--text-muted)]">Selecciona un nodo para localizarlo en el explorador de canon.</p>{entities.length < 2 ? <p className="mt-4 rounded-xl border border-dashed border-indigo-500/30 p-4 text-xs text-[var(--text-muted)]">Necesitas al menos dos entidades para visualizar conexiones.</p> : <div className="mt-4 overflow-x-auto rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)]"><svg viewBox={`0 0 ${width} ${height}`} className="min-w-[680px]" role="img" aria-label="Mapa visual de relaciones del canon">{edges.map((edge) => { const from = positions.get(edge.source); const to = positions.get(edge.target); return <line key={edge.id} x1={from.x} y1={from.y} x2={to.x} y2={to.y} stroke="currentColor" className="text-indigo-300" strokeWidth="2" />; })}{entities.map((entity) => { const point = positions.get(entity.name); return <g key={entity.id} role="button" tabIndex="0" onClick={() => onSelectEntity?.(entity.name)} className="cursor-pointer"><circle cx={point.x} cy={point.y} r="29" className="fill-indigo-500/15 stroke-indigo-500" strokeWidth="2" /><text x={point.x} y={point.y + 4} textAnchor="middle" className="fill-[var(--text-main)] text-[11px] font-bold">{entity.name.slice(0, 17)}</text></g>; })}</svg></div>}</section>;

};

const ConstructorGlobal = () => {
    const room = getToolRoom('global-constructor');
    const launch = useToolRoomLaunch('global-constructor');
    const { activeBook, activeChapter, chapters = [], worldItems = [], characters = [], profile, selectChapter, openWorldDoc, openCharacterDoc, updateChapter, updateWorldItem, updateCharacter } = useData();
    const { getRoomState, updateRoomState } = useToolRooms();
    const storedRoomState = getRoomState('global-constructor');
    const migration = migrateRoomState(storedRoomState);
    const state = migration.state;
    const [step, setStep] = useState(() => state.result ? 'review' : 'type');
    const [type, setType] = useState(launch?.mission?.type || state.mission?.type || 'develop_canon');
    const [objective, setObjective] = useState(launch?.prompt || state.mission?.objective || '');
    const [scope, setScope] = useState(state.mission?.scope || 'automatic');
    const [selectedIds, setSelectedIds] = useState(state.mission?.selectedIds || []);
    const [focusedEntity, setFocusedEntity] = useState(null);
    const [showCanonExplorer, setShowCanonExplorer] = useState(false);
    const [impact, setImpact] = useState(state.impact || null);
    const [result, setResult] = useState(state.result || null);
    const [status, setStatus] = useState(() => state.result ? 'review' : 'idle');
    const [error, setError] = useState('');
    const [staleDetected, setStaleDetected] = useState(false);
    const [snapshots, setSnapshots] = useState([]);
    const [canonSyncStatus, setCanonSyncStatus] = useState(() => (typeof navigator !== 'undefined' && navigator.onLine === false ? 'pending' : 'local'));
    const [approved, setApproved] = useState(new Set());
    const [missionId] = useState(() => state.mission?.id || `global-${Date.now()}`);
    const [canonGraph, setCanonGraph] = useState(() => loadCanonGraph(activeBook?.id));
    const [missionHistory, setMissionHistory] = useState(() => loadMissionHistory(activeBook?.id));

    useEffect(() => {
        if (migration.changed) updateRoomState('global-constructor', migration.state);
    }, [migration.changed, migration.state, updateRoomState]);

    useEffect(() => {
        const handleOnline = () => { flushPendingCanonSync(activeBook?.id).then((synced) => setCanonSyncStatus(synced ? 'synced' : 'pending')); };
        const handleOffline = () => setCanonSyncStatus('pending');
        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);
        return () => { window.removeEventListener('online', handleOnline); window.removeEventListener('offline', handleOffline); };
    }, [activeBook?.id]);

    useEffect(() => {
        // Book changes require replacing the local cache for the newly active book.
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setCanonGraph(loadCanonGraph(activeBook?.id));
        setMissionHistory(loadMissionHistory(activeBook?.id));
        let cancelled = false;
        loadCanonGraphRemote(activeBook?.id).then((remote) => {
            if (!cancelled && remote) { setCanonGraph(remote); saveCanonGraph(activeBook?.id, remote); setCanonSyncStatus('synced'); }
        });
        return () => { cancelled = true; };
    }, [activeBook?.id]);

    const documents = useMemo(() => buildMissionDocuments({ chapters, worldItems, characters, activeChapter, scope, selectedIds }), [activeChapter, chapters, characters, scope, selectedIds, worldItems]);
    useEffect(() => {
        if (!activeBook?.id || !result?.operations?.length) return;
        const targets = [...new Set(result.operations.map((operation) => operation.documentId).filter(Boolean))].slice(0, 12);
        let cancelled = false;
        Promise.all(targets.map(async (documentId) => {
            const document = documents.find((item) => item.id === documentId);
            if (!document) return [];
            const collection = document.type === 'chapter' ? 'chapters' : document.type === 'character' ? 'characters' : 'world';
            try { return (await getEntitySnapshots(activeBook.id, collection, documentId)).slice(0, 4).map((snapshot) => ({ ...snapshot, documentId, title: document.title, type: document.type, trigger: snapshot.triggerType || 'persistente', createdAt: snapshot.createdAt?.toDate ? snapshot.createdAt.toDate().toISOString() : snapshot.createdAt || new Date().toISOString() })); } catch { return []; }
        })).then((groups) => { if (!cancelled) setSnapshots((current) => [...groups.flat(), ...current].filter((item, index, all) => all.findIndex((candidate) => candidate.id === item.id) === index).slice(0, 30)); });
        return () => { cancelled = true; };
    }, [activeBook?.id, documents, result?.operations]);
    const mission = useMemo(() => ({ id: missionId, roomId: 'global-constructor', type, objective: objective.trim(), scope, selectedIds, constraints: DEFAULT_CONSTRAINTS }), [missionId, objective, scope, selectedIds, type]);

    const persistMission = (patch = {}) => updateRoomState('global-constructor', { mission: { ...mission, ...patch }, missionStatus: patch.status || 'draft' });
    const recordHistory = (patch = {}) => setMissionHistory(saveMissionHistoryEntry(activeBook?.id, { id: mission.id, mission, impact, result, ...patch }));
    const persistCanon = (nextGraph) => { const saved = saveCanonGraph(activeBook?.id, nextGraph); setCanonGraph(saved); setCanonSyncStatus('syncing'); saveCanonGraphRemote(activeBook?.id, saved).then((synced) => setCanonSyncStatus(synced ? 'synced' : 'pending')); return saved; };
    const openDocument = (documentId) => {
        const document = documents.find((item) => item.id === documentId);
        if (!document) return;
        if (document.type === 'chapter') { const chapter = chapters.find((item) => item.id === documentId); if (chapter) selectChapter(chapter); }
        else if (document.type === 'character') openCharacterDoc(documentId);
        else openWorldDoc(documentId);
    };
    const createSnapshot = async (document, trigger) => {
        const collection = document.type === 'chapter' ? 'chapters' : document.type === 'character' ? 'characters' : 'world';
        const saved = await saveEntitySnapshot(activeBook.id, collection, document.id, document.content, trigger);
        setSnapshots((current) => [{ id: saved.id, documentId: document.id, title: document.title, type: document.type, content: document.content, trigger, createdAt: new Date().toISOString() }, ...current.filter((item) => item.documentId !== document.id)]);
    };
    const restoreSnapshot = async (snapshot) => {
        if (!snapshot?.content || !activeBook) return;
        const document = documents.find((item) => item.id === snapshot.documentId);
        if (!document || !window.confirm(`¿Restaurar ${snapshot.title}? Se creará un snapshot del contenido actual antes de reemplazarlo.`)) return;
        try {
            await createSnapshot(document, 'before-restore');
            if (document.type === 'chapter') { await updateChapter(document.id, { content: snapshot.content }, { immediate: true }); await saveLocalSnapshot(document.id, snapshot.content, 'restore-global-constructor'); }
            else if (document.type === 'character') await updateCharacter(document.id, { description: snapshot.content }, { immediate: true });
            else await updateWorldItem(document.id, { content: snapshot.content }, { immediate: true });
            setError(''); setStaleDetected(false); recordHistory({ status: 'restored', restoredDocumentId: document.id });
        } catch (restoreError) { setError(restoreError?.message || 'No se pudo restaurar el snapshot.'); setStatus('error'); }
    };
    const analyze = async () => {
        if (!objective.trim()) return setError('Escribe un objetivo antes de analizar la misión.');
        setStatus('analyzing'); setError(''); setStaleDetected(false); setSnapshots([]); persistMission({ status: 'analyzing' });
        try { const nextImpact = await requestMissionImpact({ profile, mission, documents }); const impactGraph = upsertCanonRelations(upsertCanonFacts(canonGraph, nextImpact.canonFacts, nextImpact.sourceDocumentIds), nextImpact.relations, nextImpact.sourceDocumentIds); const entitySources = new Map(); nextImpact.canonFacts.forEach((fact) => [fact.subject, fact.object].forEach((name) => { if (!name) return; entitySources.set(name, [...new Set([...(entitySources.get(name) || []), ...(fact.sourceDocumentIds || nextImpact.sourceDocumentIds || [])])]); })); nextImpact.relations.forEach((relation) => [relation.source, relation.target].forEach((name) => { if (name && !entitySources.has(name)) entitySources.set(name, nextImpact.sourceDocumentIds || []); })); const discoveredEntities = [...entitySources.entries()].map(([name, sourceDocumentIds]) => ({ name, type: 'concept', status: 'proposed', sourceDocumentIds })); const nextGraph = persistCanon(upsertCanonEntities(impactGraph, discoveredEntities)); setCanonGraph(nextGraph); setImpact(nextImpact); setStep('impact'); setStatus('ready'); persistMission({ status: 'ready_for_generation', impact: nextImpact }); recordHistory({ impact: nextImpact, status: 'ready_for_generation' }); } catch (requestError) { setError(requestError?.message || 'No se pudo analizar el impacto.'); setStatus('error'); persistMission({ status: 'failed' }); recordHistory({ status: 'failed', error: requestError?.message || 'Impacto fallido' }); }
    };
    const generate = async () => {
        setStatus('generating'); setError(''); persistMission({ status: 'generating' });
        try { const nextResult = await requestMissionOperations({ profile, mission, documents, impact }); const operations = prepareOperations(nextResult.operations, documents); const prepared = { ...nextResult, operations }; setResult(prepared); setApproved(new Set()); setStep('review'); setStatus('review'); persistMission({ status: 'ready_for_review', operations }); recordHistory({ result: prepared, status: 'ready_for_review' }); } catch (requestError) { setError(requestError?.message || 'No se pudieron preparar las operaciones.'); setStatus('error'); persistMission({ status: 'failed' }); recordHistory({ status: 'failed', error: requestError?.message || 'Generación fallida' }); }
    };
    const regenerateDocument = async (documentId) => {
        const targetDocuments = documents.filter((document) => document.id === documentId);
        if (!targetDocuments.length || !impact) return;
        setStatus('generating'); setError(''); setStaleDetected(false);
        try {
            const nextResult = await requestMissionOperations({ profile, mission, documents: targetDocuments, impact: { ...impact, affectedDocuments: impact.affectedDocuments.filter((document) => document.documentId === documentId) } });
            const nextOperations = prepareOperations(nextResult.operations, targetDocuments);
            setResult((current) => current ? { ...current, summary: nextResult.summary || current.summary, operations: [...current.operations.filter((operation) => operation.documentId !== documentId), ...nextOperations] } : current);
            setStatus('review'); setStep('review'); recordHistory({ status: 'ready_for_review', regeneratedDocumentId: documentId, result: nextResult });
        } catch (regenerationError) { setStatus('error'); setError(regenerationError?.message || 'No se pudo regenerar el documento.'); }
    };
    const applyOperation = async (operation) => {
        const document = documents.find((item) => item.id === operation.documentId);
        if (!document || !activeBook) return;
        const validation = validateOperationAgainstDocument(operation, document);
        if (!validation.valid) throw new Error(`${validation.reason} Regenera la misión antes de aplicar.`);
        const nextContent = validation.nextContent;
        await createSnapshot(document, 'before-global-constructor');
        if (document.type === 'chapter') { await updateChapter(document.id, { content: nextContent }, { immediate: true }); await saveLocalSnapshot(document.id, nextContent, 'global-constructor'); }
        else if (document.type === 'character') await updateCharacter(document.id, { description: nextContent }, { immediate: true });
        else await updateWorldItem(document.id, { content: nextContent }, { immediate: true });
    };
    const approveOperation = async (id) => {
        const operation = result?.operations.find((item) => item.id === id);
        if (!operation || ['review', 'create'].includes(operation.action) || approved.has(id)) {
            if (operation && operation.action === 'create') setResult((current) => current ? { ...current, operations: current.operations.map((item) => item.id === id ? { ...item, status: 'proposed' } : item) } : current);
            return;
        }
        if (operation.action === 'fact') {
            const nextGraph = persistCanon(setCanonFactStatusByTriple(canonGraph, operation, 'canon'));
            setCanonGraph(nextGraph);
            setApproved((current) => new Set([...current, id]));
            setResult((current) => current ? { ...current, operations: current.operations.map((item) => item.id === id ? { ...item, status: 'canon' } : item) } : current);
            return;
        }
        try { await applyOperation(operation); setApproved((current) => new Set([...current, id])); setResult((current) => current ? { ...current, operations: current.operations.map((item) => item.id === id ? { ...item, status: 'applied' } : item) } : current); recordHistory({ result: { ...result, operations: result.operations.map((item) => item.id === id ? { ...item, status: 'applied' } : item) }, status: 'partially_applied' }); } catch (applyError) { const isStale = applyError?.message?.includes('cambió') || applyError?.message?.includes('coincide'); setStaleDetected(Boolean(isStale)); setError(applyError?.message || 'No se pudo aplicar la operación.'); setStatus('error'); persistMission({ status: isStale ? 'stale' : 'failed' }); recordHistory({ status: isStale ? 'stale' : 'failed', error: applyError?.message || 'Aplicación fallida' }); }
    };
    const applyPendingAsTransaction = async () => {
        const pending = result?.operations.filter((operation) => ['patch', 'replace'].includes(operation.action) && !approved.has(operation.id) && operation.status !== 'applied') || [];
        if (pending.length < 2) return;
        setStatus('applying'); setError('');
        try {
            await executeOperationsWithRollback({
                operations: pending,
                documents,
                approvedOperationIds: new Set(pending.map((operation) => operation.id)),
                apply: async (operation, nextContent, document) => {
                    await createSnapshot(document, 'before-global-transaction');
                    if (document.type === 'chapter') { await updateChapter(document.id, { content: nextContent }, { immediate: true }); await saveLocalSnapshot(document.id, nextContent, 'global-transaction'); }
                    else if (document.type === 'character') await updateCharacter(document.id, { description: nextContent }, { immediate: true });
                    else await updateWorldItem(document.id, { content: nextContent }, { immediate: true });
                },
                rollback: async (operation, document) => {
                    if (document.type === 'chapter') await updateChapter(document.id, { content: document.content }, { immediate: true });
                    else if (document.type === 'character') await updateCharacter(document.id, { description: document.content }, { immediate: true });
                    else await updateWorldItem(document.id, { content: document.content }, { immediate: true });
                },
            });
            const appliedIds = new Set(pending.map((operation) => operation.id));
            setApproved((current) => new Set([...current, ...appliedIds]));
            const nextResult = result ? { ...result, operations: result.operations.map((operation) => appliedIds.has(operation.id) ? { ...operation, status: 'applied' } : operation) } : result;
            setResult(nextResult); setStatus('review'); persistMission({ status: 'applied', operations: nextResult?.operations }); recordHistory({ result: nextResult, status: 'applied' });
        } catch (transactionError) { const isStale = transactionError?.message?.includes('cambió') || transactionError?.message?.includes('coincide'); setStaleDetected(Boolean(isStale)); setError(transactionError?.message || 'La misión no pudo aplicarse y se revirtió lo que había avanzado.'); setStatus(isStale ? 'error' : 'review'); persistMission({ status: isStale ? 'stale' : 'failed' }); recordHistory({ status: isStale ? 'stale' : 'failed', error: transactionError?.message || 'Transacción revertida' }); }
    };
    const rejectOperation = (id) => setResult((current) => current ? { ...current, operations: current.operations.map((item) => item.id === id ? { ...item, status: 'pending_review' } : item) } : current);
    const updateOperation = (id, replacementText) => setResult((current) => current ? { ...current, operations: current.operations.map((item) => item.id === id ? { ...item, replacementText } : item) } : current);
    const busy = status === 'analyzing' || status === 'generating' || status === 'applying';

    const syncLabel = { local: 'Canon local', syncing: 'Sincronizando canon…', synced: 'Canon sincronizado', pending: 'Canon pendiente de sincronizar' }[canonSyncStatus];
    return <ToolRoomShell room={room} status={busy ? 'processing' : result ? 'saved' : 'ready'} context={<div className="flex items-center gap-3"><ShieldCheck size={17} className={canonSyncStatus === 'synced' ? 'text-emerald-500' : canonSyncStatus === 'pending' ? 'text-amber-500' : 'text-indigo-500'} /><span>{syncLabel} · {documents.length} documentos disponibles</span></div>}>
        <div className="mx-auto max-w-6xl"><div className="rounded-3xl border border-indigo-500/20 bg-gradient-to-br from-indigo-500/10 via-[var(--bg-editor)] to-[var(--bg-editor)] p-6 lg:p-8"><div className="flex flex-wrap items-start justify-between gap-5"><div><p className="text-[9px] font-black uppercase tracking-[0.2em] text-indigo-500">Centro de mando narrativo</p><h2 className="mt-2 text-3xl font-serif font-black">Constructor Global</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-[var(--text-muted)]">Crea y modifica el canon de tu obra con impacto visible, contexto global y aprobación humana.</p></div><div className="rounded-2xl bg-indigo-500/10 p-3 text-indigo-500"><Sparkles size={24} /></div></div><div className="mt-7 grid grid-cols-5 gap-1 text-center text-[9px] font-black uppercase tracking-wider text-[var(--text-muted)]">{['Tipo', 'Objetivo', 'Alcance', 'Impacto', 'Revisión'].map((label, index) => <div key={label} className={`rounded-lg px-2 py-2 ${(['type', 'objective', 'scope', 'impact', 'review'].indexOf(step) >= index) ? 'bg-indigo-500/10 text-indigo-600' : 'bg-[var(--bg-app)]'}`}>{index + 1}. {label}</div>)}</div></div>
            <MissionStatusBar status={status} step={step} mission={mission} documents={documents} impact={impact} result={result} />
            {step === 'type' && <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><h3 className="text-xl font-serif font-black">¿Qué quieres hacer con tu obra?</h3><p className="mt-2 text-sm text-[var(--text-muted)]">El capítulo es opcional: comienza por la intención y deja que el Constructor determine el alcance.</p><div className="mt-6 grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">{MODE_CARDS.map(([id, Icon, label, description]) => <button key={id} type="button" onClick={() => { setType(id); setStep('objective'); }} className={`rounded-2xl border p-4 text-left transition-all ${type === id ? 'border-indigo-500 bg-indigo-500/10' : 'border-[var(--border-main)] hover:-translate-y-0.5 hover:border-indigo-500/50'}`}>{React.createElement(Icon, { size: 20, className: 'text-indigo-500' })}<h4 className="mt-4 text-sm font-black">{label}</h4><p className="mt-1 text-xs leading-relaxed text-[var(--text-muted)]">{description}</p></button>)}</div></section>}
            {step === 'objective' && <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><button type="button" onClick={() => setStep('type')} className="inline-flex items-center gap-2 text-xs font-black text-[var(--text-muted)]"><ArrowLeft size={14} /> Cambiar tipo</button><p className="mt-6 text-[9px] font-black uppercase tracking-[0.18em] text-indigo-500">{typeLabel(type)}</p><h3 className="mt-2 text-2xl font-serif font-black">¿Qué quieres conseguir?</h3><textarea autoFocus value={objective} onChange={(event) => setObjective(event.target.value)} rows={5} placeholder="Ej. Define el origen de Narev y sincroniza cualquier capítulo o personaje que dependa de ese hecho…" className="mt-5 w-full resize-none rounded-2xl border border-[var(--border-main)] bg-[var(--bg-app)] p-4 text-sm outline-none focus:border-indigo-500" /><div className="mt-4 flex flex-wrap gap-2">{['Define una regla canónica', 'Actualiza Información general', 'Sincroniza con la obra', 'Encuentra contradicciones'].map((suggestion) => <button type="button" key={suggestion} onClick={() => setObjective(suggestion)} className="rounded-full border border-[var(--border-main)] px-3 py-1.5 text-xs font-bold hover:border-indigo-500 hover:text-indigo-500">{suggestion}</button>)}</div><div className="mt-6 flex justify-end"><button type="button" disabled={!objective.trim()} onClick={() => setStep('scope')} className="inline-flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-3 text-sm font-black text-white disabled:opacity-50">Configurar alcance <ChevronRight size={16} /></button></div></section>}
            {step === 'scope' && <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><button type="button" onClick={() => setStep('objective')} className="inline-flex items-center gap-2 text-xs font-black text-[var(--text-muted)]"><ArrowLeft size={14} /> Volver al objetivo</button><h3 className="mt-6 text-2xl font-serif font-black">¿Dónde debe trabajar?</h3><div className="mt-5 grid grid-cols-1 gap-3 md:grid-cols-2">{MISSION_SCOPES.map((option) => <button type="button" key={option.id} onClick={() => setScope(option.id)} className={`rounded-2xl border p-4 text-left ${scope === option.id ? 'border-indigo-500 bg-indigo-500/10' : 'border-[var(--border-main)]'}`}><p className="text-sm font-black">{option.label}</p><p className="mt-1 text-xs leading-relaxed text-[var(--text-muted)]">{option.description}</p></button>)}</div>{scope === 'selected' && <MissionDocumentPicker documents={buildMissionDocuments({ chapters, worldItems, characters, activeChapter, scope: 'all' })} selectedIds={selectedIds} setSelectedIds={setSelectedIds} />}<div className="mt-6 rounded-2xl border border-emerald-500/20 bg-emerald-500/5 p-4 text-sm leading-relaxed text-[var(--text-muted)]"><strong className="text-[var(--text-main)]">Contexto base incluido:</strong> Información general, Estructura y el manuscrito o entidades que correspondan al alcance.</div><div className="mt-6 flex justify-end"><button type="button" onClick={analyze} disabled={busy || (scope === 'selected' && selectedIds.length === 0)} className="inline-flex items-center gap-2 rounded-xl bg-cyan-600 px-4 py-3 text-sm font-black text-white disabled:opacity-50">{busy ? <Loader2 size={16} className="animate-spin" /> : <Search size={16} />} {busy ? 'Analizando impacto…' : 'Analizar impacto'}</button></div></section>}
            {step === 'impact' && <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><button type="button" onClick={() => setStep('scope')} className="inline-flex items-center gap-2 text-xs font-black text-[var(--text-muted)]"><ArrowLeft size={14} /> Ajustar alcance</button><ImpactPanel impact={impact} onContinue={generate} /></section>}
            {step === 'review' && <section className="mt-5 rounded-3xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-5 lg:p-7"><button type="button" onClick={() => setStep('impact')} className="inline-flex items-center gap-2 text-xs font-black text-[var(--text-muted)]"><ArrowLeft size={14} /> Volver al impacto</button><ReviewPanel result={result} pendingCount={result?.operations.filter((operation) => ['patch', 'replace'].includes(operation.action) && operation.status !== 'applied').length || 0} onApplyApproved={applyPendingAsTransaction} onApprove={approveOperation} onReject={rejectOperation} onEdit={updateOperation} onRegenerateDocument={regenerateDocument} />{result?.operations.every((operation) => operation.status === 'applied' || operation.action === 'review' || operation.action === 'fact') && <div className="mt-5 flex items-center gap-2 rounded-xl bg-emerald-500/10 p-3 text-xs font-black text-emerald-700"><CheckCircle2 size={16} /> Misión aplicada parcialmente. Las operaciones informativas permanecen como revisión.</div>}</section>}
            {error && <div className="mt-5 flex items-start gap-2 rounded-2xl border border-red-500/25 bg-red-500/5 p-4 text-xs text-red-600"><AlertTriangle size={15} className="mt-0.5 shrink-0" /><div className="min-w-0 flex-1"><p>{error}</p>{staleDetected && <button type="button" onClick={() => { setResult(null); setImpact(null); setError(''); setStaleDetected(false); setStep('scope'); persistMission({ status: 'configured' }); }} className="mt-3 inline-flex items-center gap-1.5 rounded-lg border border-red-500/30 px-2.5 py-1.5 font-black hover:bg-red-500/10"><RefreshCw size={13} /> Actualizar análisis y regenerar</button>}</div><button type="button" onClick={() => setError('')} className="ml-auto"><X size={14} /></button></div>}
            <CanonPanel graph={canonGraph} onStatusChange={(id, nextStatus, kind) => { persistCanon(setCanonItemStatus(canonGraph, id, nextStatus, kind)); }} />
            <section className="mt-5 rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[9px] font-black uppercase tracking-[0.16em] text-[var(--text-muted)]">Explorar</p><h3 className="mt-1 text-sm font-black">Dependencias y relaciones</h3><p className="mt-1 text-xs text-[var(--text-muted)]">Investiga entidades, apariciones y conexiones cuando necesites profundizar.</p></div><button type="button" onClick={() => setShowCanonExplorer((current) => !current)} className="inline-flex items-center gap-2 rounded-xl border border-indigo-500/30 px-3 py-2 text-xs font-black text-indigo-600 hover:bg-indigo-500/10">{showCanonExplorer ? 'Ocultar exploración' : 'Explorar canon'} <ChevronRight size={14} className={showCanonExplorer ? 'rotate-90' : ''} /></button></div></section>
            {showCanonExplorer && <div><EntityExplorer graph={canonGraph} documents={documents} onGraphChange={persistCanon} onOpenDocument={openDocument} focusName={focusedEntity} /><RelationCanvas graph={canonGraph} onSelectEntity={setFocusedEntity} /></div>}
            <SnapshotPanel snapshots={snapshots} onRestore={restoreSnapshot} /><MissionHistoryPanel entries={missionHistory} /><div className="mt-5 grid grid-cols-2 gap-3 md:grid-cols-4"><div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-4"><p className="text-2xl font-black">{chapters.filter((item) => !item.isVolume).length}</p><p className="text-xs text-[var(--text-muted)]">Capítulos</p></div><div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-4"><p className="text-2xl font-black">{worldItems.length}</p><p className="text-xs text-[var(--text-muted)]">Canon y mundo</p></div><div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-4"><p className="text-2xl font-black">{characters.length}</p><p className="text-xs text-[var(--text-muted)]">Personajes</p></div><div className="rounded-2xl border border-[var(--border-main)] bg-[var(--bg-editor)] p-4"><p className="text-2xl font-black">{documents.length}</p><p className="text-xs text-[var(--text-muted)]">Contexto disponible</p></div></div>
        </div>
    </ToolRoomShell>;
};

export default ConstructorGlobal;
